import{GARDEN_CONFIG as u}from"./config.min.js";export const SPRING="spring",SUMMER="summer",AUTUMN="autumn",WINTER="winter",HOURS_PER_DAY=24;export function hourAt(r,t=u.clock.cycleSeconds){if(!(t>0))return 0;const o=r/t;return(o-Math.floor(o))*HOURS_PER_DAY}export function yearAt(r,t=u.clock.cycleSeconds){return t>0?r/t:0}export function startSeconds(r=u.clock){return wrapHour(r.startHour||0)/HOURS_PER_DAY*r.cycleSeconds}export function yearPhaseAt(r){return wrapHour(r)/HOURS_PER_DAY}export function wrapHour(r){const t=r%HOURS_PER_DAY;return t<0?t+HOURS_PER_DAY:t}export function seasonAt(r,t=u.season.boundaries){const o=wrapHour(r);return o>t.spring&&o<=t.summer?SPRING:o>t.summer&&o<=t.autumn?SUMMER:o>t.autumn&&o<=t.winter?AUTUMN:WINTER}export function seasonPhaseAt(r,t=u.season.boundaries){const o=wrapHour(r),e=seasonAt(o,t),n={[SPRING]:t.spring,[SUMMER]:t.summer,[AUTUMN]:t.autumn,[WINTER]:t.winter},c=HOURS_PER_DAY/4;return wrapHour(o-n[e])/c}export function inThirstWindow(r,t=u.season.thirst){const o=wrapHour(r);return o>t.start&&o<=t.end}export function solarAt(r,t=u.sun){const o=wrapHour(r),e=t.maxElevation*Math.sin((o-6)*Math.PI/12),n=(o-12)*15;return{elevation:e,azimuth:n}}export function lunarAt(r,t=u.sun){const o=solarAt(r,t);return{elevation:-o.elevation,azimuth:o.azimuth+180}}export function snowCoverageAt(r,t=u.season){const o=t.snow,e=t.boundaries.winter,n=wrapHour(r-e),c=f=>wrapHour(f-e),s=c(o.firstFlakes),i=c(o.accumulatedBy),a=c(o.holdUntil),d=c(o.meltBy);return n<s?0:n<i?smoothstep((n-s)/(i-s)):n<a?1:n<d?1-smoothstep((n-a)/(d-a)):0}export function isSnowingAt(r,t=u.season){const o=t.snow,e=t.boundaries.winter,n=wrapHour(r-e);return n>=wrapHour(o.firstFlakes-e)&&n<wrapHour(o.holdUntil-e)}export function phenologyAt(r,t=!1,o=u.season){const e=wrapHour(r),n=o.phenology;if(t)return{bud:0,leaf:1,color:Math.max(0,-Math.sin((e-6)*Math.PI/12))*n.evergreenWinterFade,drop:0};if(e>n.dropEnd||e<=n.budStart)return{bud:0,leaf:0,color:1,drop:1};if(e<=n.budEnd){const s=(e-n.budStart)/(n.budEnd-n.budStart);return{bud:smoothstep(s),leaf:s*n.budLeafSize,color:0,drop:0}}if(e<=n.expandEnd){const s=(e-n.budEnd)/(n.expandEnd-n.budEnd);return{bud:1,leaf:n.budLeafSize+(1-n.budLeafSize)*smoothstep(s),color:0,drop:0}}if(e<=n.turnStart)return{bud:1,leaf:1,color:0,drop:0};if(e<=n.turnEnd){const s=(e-n.turnStart)/(n.turnEnd-n.turnStart);return{bud:1,leaf:1,color:smoothstep(s),drop:0}}const c=(e-n.dropStart)/(n.dropEnd-n.dropStart);return{bud:1,leaf:1,color:1,drop:smoothstep(clamp01(c))}}export function clamp01(r){return r<0?0:r>1?1:r}export function smoothstep(r){const t=clamp01(r);return t*t*(3-2*t)}
